/**
 * A person's due-total: the figures of their claims that count (an unbound OPEN one not when dated within one of `holds`: a retired person's, see `liveHolds`) (each at the rate in force on its
 * date for their grade in force on its date), added up, skipping n/a. With no rate for their grade
 * today it is n/a, unless a claim that counts keeps a fixed figure (settled, or bound by a
 * statement), has a figure under another grade in force on its date, or has a figure dated on or
 * before today (under a rate that has since ended). A shared claim counts its due less its holders'
 * parts; the parts `held` of others' claims shared with them count too (and keep it from n/a). Held to
 * the sheet's `cap` ('' for none); n/a is not capped.
 */
export function personDueTotal(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  cap: string,
  held: HeldPart[] = [],
): string {
  const total = uncappedDueTotal(rates, grades, today, claims, holds, floor, late, held);
  if (total === NA || cap === '' || hundredths(total) <= hundredths(cap)) return total;
  return showCents(hundredths(cap));
}

/** How far a person's due-total, before the sheet's `cap` ('' for none), goes above it: 0.00 when it does not. */
export function personExcess(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  cap: string,
  held: HeldPart[] = [],
): string {
  const total = uncappedDueTotal(rates, grades, today, claims, holds, floor, late, held);
  if (total === NA || cap === '' || hundredths(total) <= hundredths(cap)) return '0.00';
  return showCents(hundredths(total) - hundredths(cap));
}

  );
}

function DueHead() {
  return <Col name="due-total"><th>Due</th></Col>;
}

// A person's due-total: the due figures of their claims that count, added up, held to the sheet's cap.
function PersonDueTotal({ sheetId, person }: { sheetId: string; person: Person }) {
  const claims = (useClaims(sheetId).data ?? []).filter((c) => c.personId === person.id);
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const held = heldParts(person.id, usePeople(sheetId).data ?? [], useClaims(sheetId).data ?? [], rates, today, floor, late);
  return <Col name="due-total"><td data-testid="person-due-total">{personDueTotal(rates, person.grades, today, claims, liveHolds(person, today), floor, late, cap, held)}</td></Col>;
}

function ExcessHead() {
  return <Col name="excess"><th>Excess</th></Col>;
}

// A person's excess: how far the due figures of their claims that count go above the sheet's cap.
function PersonExcess({ sheetId, person }: { sheetId: string; person: Person }) {
  const claims = (useClaims(sheetId).data ?? []).filter((c) => c.personId === person.id);
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const held = heldParts(person.id, usePeople(sheetId).data ?? [], useClaims(sheetId).data ?? [], rates, today, floor, late);
  return <Col name="excess"><td data-testid="person-excess">{personExcess(rates, person.grades, today, claims, liveHolds(person, today), floor, late, cap, held)}</td></Col>;
}

// The sheet's due-total: everyone's due-total added up, skipping those with no rate, trimmed of the highest and lowest.
function DueTotal({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const totals = people.map((p) =>
    personDueTotal(rates, p.grades, today, claims.filter((c) => c.personId === p.id), liveHolds(p, today), floor, late, cap,
      heldParts(p.id, people, claims, rates, today, floor, late)),
  );
  return (
    <p>
      Due in all: <strong data-testid="rollup-due-total">{trimmedSumDue(totals)}</strong>
    </p>
  );
}

function SplitHead() {
  return (
    <>
      <th>Settled</th>
      <th>Open</th>
    </>
  );
}

